package br.com.onda;
import android.content.Context;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import java.io.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
public class LionBrandTest {
 @Test public void goldenLionIsLauncherIconAndOneStaticSharedPlaceholder()throws Exception{Context c=getInstrumentation().getTargetContext();Bitmap shared=LionBrand.bitmap(c);assertSame(shared,LionBrand.bitmap(c));assertTrue(shared.getWidth()>=256&&shared.getWidth()<=384);assertTrue(shared.getAllocationByteCount()<=512*1024);assertEquals(R.drawable.ic_onda,c.getPackageManager().getApplicationInfo(c.getPackageName(),0).icon);Bitmap launcher=Bitmap.createBitmap(96,96,Bitmap.Config.ARGB_8888),placeholder=Bitmap.createBitmap(96,96,Bitmap.Config.ARGB_8888);try{Drawable icon=c.getPackageManager().getApplicationIcon(c.getPackageName());getInstrumentation().runOnMainSync(()->{icon.setBounds(0,0,96,96);icon.draw(new Canvas(launcher));View view=Ui.art(c,48,0);view.measure(View.MeasureSpec.makeMeasureSpec(96,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(96,View.MeasureSpec.EXACTLY));view.layout(0,0,96,96);view.draw(new Canvas(placeholder));});assertFalse(icon instanceof Animatable);int gold=0;for(int y=0;y<96;y++)for(int x=0;x<96;x++){int color=placeholder.getPixel(x,y);if(Color.alpha(color)>200&&Color.red(color)>150&&Color.green(color)>65&&Color.blue(color)<160)gold++;}assertTrue("Golden lion pixels missing",gold>1500);int launcherGold=0;for(int y=0;y<96;y++)for(int x=0;x<96;x++){int color=launcher.getPixel(x,y);if(Color.alpha(color)>200&&Color.red(color)>150&&Color.green(color)>65&&Color.blue(color)<160)launcherGold++;}assertTrue(launcherGold>1500);getInstrumentation().runOnMainSync(()->{for(AppearancePalette palette:AppearancePalette.ALL){Ui.install(palette);assertSame(shared,LionBrand.bitmap(c));}});try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"lion-brand-preview.png"))){placeholder.compress(Bitmap.CompressFormat.PNG,100,out);}JSONObject proof=new JSONObject().put("launcherIcon",true).put("goldPixels",gold).put("launcherGoldPixels",launcherGold).put("sharedBitmap",true).put("decodedWidth",shared.getWidth()).put("bitmapBytes",shared.getAllocationByteCount()).put("themesChecked",AppearancePalette.ALL.length).put("staticDrawable",true);java.nio.file.Files.write(new File(c.getFilesDir(),"lion-brand-tests.json").toPath(),proof.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}finally{launcher.recycle();placeholder.recycle();Ui.install(AppearancePalette.find(c.getSharedPreferences("appearance",0).getString("theme","original")));}}
}
